void Vote(int winner)
{
    voted = true;
    headerA.Text = "Claude Opus 5.5";
    headerB.Text = "GPT-6.1 Sol";
    resultText.Text = winner == 0 ? "You picked Model A · Claude Opus 5.5"
        : winner == 1 ? "You picked Model B · GPT-6.1 Sol"
        : "You called it a tie";
    result.IsVisible = true;
    status.Text = "Vote recorded. The two model names are revealed.";
}
